export const PROVENANCE = {"source":"origin.html","sourceSha256":"86f7c110a82587eb50f302def2261b5ae9b431a41cdabf46b8f48a6c7a8f0668","edition":"3.4","alphabet":"Luma Origin · articulatory alphabet laboratory","codingConventions":["This is an authored binary coding convention for twenty target phonemes, not a complete IPA feature theory or an acoustic measurement.","A zero means that the feature is not asserted in this coding. It does not necessarily claim a universal articulatory absence.","Vocalic identifies syllabic vowel targets. Sonorant includes vowels, nasals, approximants and the tap.","Continuant means sustained oral or glottal airflow without a complete oral closure: vowels, fricatives and approximants are 1; oral stops, nasals and the tap are 0. Nasals sustain nasal airflow, which this coordinate deliberately does not represent.","Labial is consonantal lip place, including the secondary lip articulation of w. Vowel lip posture is encoded separately by rounded, avoiding an assertion that vowels share a primary consonant place.","Coronal groups alveolar tongue-tip/blade consonants. Dorsal identifies a tongue-body articulation, including vowels and the palatal/velar approximants. These broad place labels do not distinguish every IPA place.","Glottal is assigned to h. Its accompanying oral vowel posture is context dependent and is not assigned a fixed oral place.","High/low/front/back encode tongue-body target posture only for vowels and w/y; no vowel height or backness is imposed on k or g. Central a has neither front nor back; mid e/o have neither high nor low.","Rounded is assigned to o, u and w. Lateral identifies l and rhotic identifies the target tap r=/ɾ/.","Voicing refers to the intended phonemic target; partial devoicing or contextual realization can occur in actual speech.","Roman a is represented broadly as /a/ with central target [ä]. Roman e/o are mid vowel targets, represented broadly as /e o/ and more specifically [e̞ o̞]. The letter y represents /j/, never the vowel [y]."],"glyphRule":"Consonants combine place carrier, manner stroke and a lower-right voiced bead; w adds a dorsal arch, l a lateral branch. Vowels share an open frame: nucleus horizontal position is front/central/back, vertical position is high/mid/low, enclosing ring means rounded. Featural glyphs are original designs; human recognizability is untested.","featureCodeRule":"sum(featureVector[i] * 2**i for i in range(16)); first listed coordinate is the least-significant bit","music":{"rule":"q=5f+u; the existing letter code selects ratios[f] then ratios[u]","ratios":["1","9/8","5/4","3/2","5/3"],"referenceHz":220,"referenceStatus":"authored reference, unchanged from earlier editions","skyLink":"The sky selects a phrase through a disclosed symbolic lens. The phrase supplies the unchanged letter music."},"adaptation":"Anima's game grammar and physical constructions are new compositions using the unchanged Luma inventory."};
